17	 */
18	@Mapper(uses = PetMapper.class,
19	    imports = {org.springframework.samples.petclinic.util.LocalityResolver.class,
20	        org.springframework.samples.petclinic.util.MembershipLevel.class,
21	        org.springframework.samples.petclinic.util.AgeBand.class,
22	        org.springframework.samples.petclinic.util.ContactPreference.class,
23	        org.springframework.samples.petclinic.util.CheckDigit.class,
24	        org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.class})
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName",
28	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
29	    @Mapping(target = "initials",
30	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
31	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
32	    @Mapping(target = "membershipLevel",
33	        expression = "java(MembershipLevel.levelOf(owner))")
34	    @Mapping(target = "locality",
35	        expression = "java(LocalityResolver.regionOfCustomerCode(owner.getCustomerCode()))")
36	    @Mapping(target = "contactPreference",
37	        expression = "java(ContactPreference.preferenceOf(owner))")
38	    @Mapping(target = "ageBand",
39	        expression = "java(AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
40	    @Mapping(target = "identityKey",
41	        expression = "java(OwnerIdentityKey.forOwner(owner))")
42	    @Mapping(target = "checkDigit",
43	        expression = "java(CheckDigit.luhnOf(owner.getCustomerCode()))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    Owner toOwner(OwnerDto ownerDto);
47	
48	    @Mapping(target = "id", ignore = true)
49	    @Mapping(target = "pets", ignore = true)
50	    Owner toOwner(OwnerFieldsDto ownerDto);
51	
52	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
53	
54	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
55	
56	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
57	        OwnerPageDto ownerPageDto = new OwnerPageDto();
58	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
59	        ownerPageDto.setPage(ownerPage.getNumber());
60	        ownerPageDto.setSize(ownerPage.getSize());
61	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
62	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
63	        return ownerPageDto;
64	    }
65	}
